const gaps={embedded_visual_semantics:'图示含义',textbox_layout_or_reading_order:'文本框布局或阅读顺序',table_layout_or_merged_cells:'表格布局或合并单元格',compatibility_display_branch_unresolved:'兼容显示差异',non_body_parts:'正文外内容',unclassified_body_container:'其他正文内容'};
