export function evidenceManualSaveStatus({dirty,localSaved}){
 if(!localSaved)return '当前人工稿仅保留在本页内存，尚未可靠保存到本机，请勿刷新或退出。';
 return dirty?'当前人工修改已在本机保护，尚未全部保存到服务器。':'已读取服务器保存稿，仍需人工核对。';
}
export function evidenceWorkingDraftLabel(saved){
 const draft=saved.structure_form;
 if(draft){
  const kinds={business:'补充业务',step:'补充步骤',participant:'补充参与方',interaction:'补充互动',condition:'补充条件',coordination:'补充协同'},fields=draft.fields||{};
  const business=draft.kind==='business'?'新增业务':draft.base_value?.result?.businesses?.[draft.business_index]?.name||'原业务待核对';
  const candidates={business:[fields.name],step:[fields.name,fields.purpose],participant:[fields.agent,fields.responsibility],interaction:[fields.purpose],condition:[fields.statement],coordination:[fields.start_rule,fields.wait_rule,fields.join_rule]}[draft.kind]||[];
  const category=(draft.kind==='coordination'?{sequence:'顺序',branch:'分支',parallel:'并行',unspecified:'尚未明确'}:draft.kind==='condition'?{precondition:'开始前提',trigger:'触发条件',stop:'停止条件',exception:'例外情况'}:{})[fields.kind];
  const entered=candidates.find(value=>typeof value==='string'&&value.trim())||(category?category+'（内容尚未填完）':typeof fields.reason==='string'&&fields.reason.trim()?fields.reason:'内容尚未填完'),chars=Array.from(entered);
  return (saved.pending?'原请求待核对；':'')+(kinds[draft.kind]||'保留的补充')+' · '+business+' · '+chars.slice(0,120).join('')+(chars.length>120?'…':'');
 }
 if(saved.pending)return '原请求待核对';
 return saved.dirty?'人工稿待保存':'已保留的人工稿';
}

export function EvidenceReadingRange({preview,Btn=Button}){
 const [view,setView]=useState('w'),[position,setPosition]=useState(1),blocks=evidenceProjection(preview.source_snapshot).blocks.filter(b=>b[0].startsWith(view+':')),i=Math.max(0,Math.min(position-1,blocks.length-1)),current=blocks[i];
 return <details><summary>查看完整外发文字与现有领域背景</summary><p>以下是本次实际选版并脱敏的文字；没有截短或删除重复来源。仅发送文字，不发送页图。</p><label>读取视图<select aria-label="证据读取文字视图" value={view} onChange={e=>{setView(e.target.value);setPosition(1);}}><option value="w">Word正文与表格文字</option><option value="o">PDF逐页已保存文字</option></select></label><label>{view==='o'?'页码':'正文位置'}<input aria-label="证据读取文字位置" type="number" min={1} max={blocks.length} value={i+1} onChange={e=>setPosition(Math.max(1,Math.min(blocks.length,Number(e.target.value)||1)))}/></label><p>本视图完整{blocks.length}{view==='o'?'页':'处正文'}。</p><blockquote>{current?.[3]||'此保存版本没有文字，不表示图示已理解。'}</blockquote><Btn disabled={!i} onClick={()=>setPosition(i)}>上一处文字</Btn><Btn disabled={i+1>=blocks.length} onClick={()=>setPosition(i+2)}>下一处文字</Btn><p>领域：{preview.map_preparation.context.profile?.domain||'未填写'}；已有业务：{preview.map_preparation.context.businesses?.join('、')||'无'}；现有对象：{preview.map_preparation.context.object_names?.join('、')||'无'}。</p></details>;
}

export function EvidenceCallPreview({preview,Btn=Button,busy,writable,pending,onStart}){
 const strict=evidenceV4(preview)||evidenceV5(preview)||claimArrayPreview(preview);
 return <section data-evidence-preview-hash={preview.preview_hash} data-evidence-request-id={preview.body.request_id} data-evidence-source-hash={preview.source_hash}>
 <h3>2. 核对全部范围，再决定提取事实</h3><p>{preview.model} · Word{preview.source_snapshot.coverage.word_blocks}段、PDF{preview.source_snapshot.coverage.selected_pages}页；完整划分{preview.input_summary.map_call_count}个资料组，逐组提取有出处的事实。</p>
 <p>本次最多{preview.input_summary.map_call_count}次调用，{strict?'发送内容大小（正文和格式要求）':'消息共'}{sentBytes(preview.input_summary,preview).toLocaleString()}字节，保守预留{preview.input_summary.map_token_bound.toLocaleString()} token。{evidenceV4(preview)?evidenceV4ReduceBlocked:'汇总业务草案最多另有1次调用，届时单独预览并明确授权，本次不会自动汇总。'}</p>
 <p>Word仍待核：{preview.source_snapshot.coverage.word_gaps.map(g=>(gaps[g.kind]||'其他待核内容')+g.count+'处').join('、')||'读取器未列新增缺口，不代表图示已理解'}。不外发页图。</p>
 {claimEnumPreview(preview)&&<p>每组回答的引用仅可选本组已提供的原文片段；仍需核对声明的含义、遗漏和推断。这项引用限制不代表报告理解质量已通过。</p>}
 <details><summary>查看各资料组范围</summary>{preview.map_preparation.plan.chunks.map((c,i)=><p key={c.chunk_id}>资料组{i+1} · {c.source_refs.length}处原文位置 · {c.span_refs.length}个片段 · {strict?'发送内容大小（正文和格式要求）':''}{sentBytes(c.input_summary,preview).toLocaleString()}字节。</p>)}</details>
 <EvidenceReadingRange preview={preview} Btn={Btn}/>{preview.start_blocker&&<p role="alert">{preview.start_blocker}</p>}<Btn primary disabled={busy||!writable||pending.length>0||!preview.can_start} onClick={onStart}>同意本次完整范围并开始提取事实</Btn></section>;
}

export function EvidenceReductionPreview({preview,readingPreview,Btn=Button,busy,writable,pending,onStart}){
 const p=preview.reduction_preparation,claimList=['report-evidence-reduction-preparation-v2','report-evidence-reduction-preparation-v3','report-claim-array-reduction-preparation-v168','report-claim-enum-reduction-preparation-v172'].includes(p.schema),count=claimList?p.payload.input_claims.length:Object.keys(p.payload.input_items).length;
 return <section data-evidence-reduce-preview={preview.preview_hash} data-evidence-reduce-request-id={preview.body.request_id}><h3>单独确认汇总业务草案</h3><p>使用{count}条已保存原声明和它们实际引用的{p.payload.spans.length}处片段；只调用1次。{evidenceV5(readingPreview)||claimArrayPreview(readingPreview)?'发送内容大小（正文和格式要求）':'完整消息'}{sentBytes(p.input_summary,readingPreview).toLocaleString()}字节，保守预留{p.input_summary.token_bound.toLocaleString()} token。</p>{p.output_capacity&&<p>本次回答最多{p.output_capacity.max_output_tokens.toLocaleString()} token；尚不能保证容纳全部内容。若回答未完整结束，只保留原回答与费用记录，不当作已生成候选。</p>}<p>每条原声明记录保留、重复或存疑去向；这不能证明解释完整正确。输出不足或失败时保存原回答，不截断、不暗加调用。</p>{preview.start_blocker&&<p role="alert">{preview.start_blocker}</p>}<Btn primary disabled={busy||!writable||pending.length>0||!preview.can_start} onClick={onStart}>同意本次范围并汇总业务草案</Btn></section>;
}

function OriginalSpan({spanRef,catalog,preview,account,Btn}){
 const span=catalog.index[spanRef],source=span?.source_ref,page=source?.startsWith('o:')?preview.source_snapshot.pages[Number(source.slice(3))-1]:null,[verified,setVerified]=useState(null);
 const key=[account.user_id,account.workspace_id,preview.source_hash,spanRef,page?.unit_id,page?.revision.hash,page?.image.sha256].join(':'),entry=useRef(key),latest=useRef(key);latest.current=key;
 const ready=useCallback(image=>{if(latest.current!==entry.current)return;if(image&&(image.materialID!==preview.source_snapshot.copy.ref.id||image.runID!==preview.source_snapshot.selection.run_id||image.unitID!==page?.unit_id||image.sha256!==page?.image.sha256||image.width!==page?.image.width||image.height!==page?.image.height))return;setVerified(image);},[key]);
 if(!span||entry.current!==key)return <p>原文片段已变化，请重新打开。</p>;
 return <section className="evidence-reading-source"><h5>{evidenceSpanLabel(spanRef)}</h5><blockquote>{span.text}</blockquote><p>本段是实际提供给模型的保存文字，仍需核对解释；不是单独的正式来源批准。</p>{page?<><p>{preview.source_snapshot.copy.name} · 第{page.page}页 · {versions[page.revision.kind]}第{page.revision.number}版。</p><MaterialOCRImage key={key} materialID={preview.source_snapshot.copy.ref.id} runID={preview.source_snapshot.selection.run_id} unit={{id:page.unit_id,width:page.image.width,height:page.image.height,image_sha256:page.image.sha256}} regions={page.regions.map(r=>({...r,box:r.box.map(Number)}))} onReady={ready} draw={false} Btn={Btn}/><small>{verified?'页图字节与尺寸已核对；尚不代表文字与图表语义正确。':'页图尚未完成字节与尺寸核对。'}脱敏后的片段位置可能与原图文字不同，不自动标成已确认选区。</small></>:<p>Word接受修订后正文位置{source.slice(3)}；此序号不是原报告页码。</p>}</section>;
}

function SpanReferences({refs,onChange,max,catalog,preview,account,writable,Btn}){
 const [search,setSearch]=useState(''),[opened,setOpened]=useState(null),provided=preview.reductionRefs||Object.keys(catalog.index),matches=search.trim()?provided.filter(ref=>!refs.includes(ref)&&(evidenceSpanLabel(ref).includes(search)||catalog.index[ref].text.includes(search))).slice(0,12):[];
 return <section className="evidence-reading-references"><h5>原文依据 · {refs.length}处</h5>{refs.map(ref=><div key={ref}><strong>{evidenceSpanLabel(ref)}</strong><blockquote>{catalog.index[ref]?.text||'此引用不在已发送范围，不能保存为有效依据。'}</blockquote><Btn onClick={()=>setOpened(opened===ref?null:ref)}>{opened===ref?'收起原文与页图':'对照原文与页图'}</Btn>{onChange&&<Btn disabled={!writable} onClick={()=>onChange(refs.filter(r=>r!==ref))}>移除此引用</Btn>}{opened===ref&&<OriginalSpan key={[account.user_id,account.workspace_id,preview.source_hash,ref].join(':')} spanRef={ref} catalog={catalog} preview={preview} account={account} Btn={Btn}/>}</div>)}{!refs.length&&<p>本项暂无字面引用，必须保留推断或待核说明。</p>}{onChange&&<details><summary>从本次实际提供的原文中调整依据</summary><label>查找原文或页码<input aria-label="查找候选原文依据" value={search} onChange={e=>setSearch(e.target.value)}/></label><p>仅列出当前汇总实际收到的原文片段，最多显示12个匹配；不从整库借用未发送内容。</p>{matches.map(ref=><article key={ref}><strong>{evidenceSpanLabel(ref)}</strong><blockquote>{catalog.index[ref].text}</blockquote><Btn disabled={!writable||refs.length>=max} onClick={()=>{onChange([...refs,ref]);setSearch('');}}>采用这处原文依据</Btn></article>)}</details>}</section>;
}

export function EvidenceSavedFacts({account,row,stage,catalog,request,checkEntry=()=>{},onSessionInvalid,Btn=Button}){
 const scope=evidenceSavedFactsScope(account,row,stage),latest=useRef(scope),owner=useRef(scope),active=useRef(true),sequence=useRef(0);latest.current=scope;
 const [opened,setOpened]=useState(false),[loading,setLoading]=useState(false),[saved,setSaved]=useState(null),[failure,setFailure]=useState(null);
 useEffect(()=>{owner.current=scope;active.current=true;sequence.current++;setOpened(false);setLoading(false);setSaved(null);setFailure(null);return()=>{active.current=false;sequence.current++;};},[scope]);
 async function read(){const entry=scope,seq=++sequence.current,check=()=>{if(!active.current||entry!==latest.current||owner.current!==entry||seq!==sequence.current)throw Error('账号、资料组或原回答版本已变化，未采用迟到内容。');checkEntry();};try{check();setOpened(true);setLoading(true);setFailure(null);const value=await readEvidenceSavedFacts({account,row,stage,request,check});check();setSaved({scope:entry,value});}catch(error){try{check();setFailure({scope:entry,message:error.detail?.message||error.message});if([401,403].includes(error.status)||error.code==='SESSION_SCOPE_CHANGED')onSessionInvalid?.();}catch{}}finally{try{check();setLoading(false);}catch{}}}
 if(scope!==owner.current)return <p>正在核对账号与资料组，暂不显示原私人回答。</p>;
 const view=saved?.scope===scope?saved.value:null,error=failure?.scope===scope?failure.message:null,refReasons={invalid:'引用格式不符合本批约定',outside_batch:'引用不在本组实际收到的原文范围',missing:'未找到可核对的原文片段'};
 return <section data-evidence-saved-facts-stage={stage} data-evidence-saved-facts-hash={view?.view_hash||''}>
 <Btn disabled={loading} onClick={read}>{view?'重新读取已保存事实（只读）':'查看已保存事实（只读）'}</Btn>{opened&&<>
 <h4>已保存原声明 · 只读查看</h4><p className="evidence-reading-warning">以下内容没有被修正或采用。原失败状态、回答、费用与请求编号保留；不会进入汇总、应用或发布，也不会调用模型。原文明示仅表示模型如此声明，含义仍须人工核对。</p>
 {loading&&<p role="status">正在读取已保存回答…</p>}{error&&<p role="alert">{error}{view?' 下方仍为此前已核对范围的只读内容。':''}</p>}{!view&&error&&<Btn disabled={loading} onClick={read}>重试读取已保存事实（只读）</Btn>}
 {view&&<><p>{view.message}</p>{view.original_protocol_valid===false&&<p role="alert">原协议检查未通过；可读声明不等于有效提取结果，尚未进入汇总。</p>}{view.protocol_issues.length>0&&<details><summary>查看原协议检查问题 · {view.protocol_issues.length}项</summary>{view.protocol_issues.map((issue,i)=><p key={i}>{issue.message}</p>)}</details>}
 {view.availability==='available'?<><p>原回答共有{view.facts.length}条声明；以下保持原数组顺序。</p>{view.facts.map(f=>{const fields=f.fields,resolved=f.references.filter(r=>r.state==='resolved');return <details key={f.display_id} open={f.position===0} data-evidence-saved-fact={f.display_id}><summary>原声明{f.position+1}：{fields.kind??'类别未以文字提供'}</summary><p>{fields.statement===null?'原回答未以文字提供声明内容。':fields.statement||'原声明文字为空。'}</p><p>原依据状态：{fields.status==='explicit'?'原文明示，仍待核':fields.status==='inferred'?'推断':fields.status==='unknown'?'未知':fields.status||'未以文字提供'}</p><p>原解释：{fields.explanation===null?'未以文字提供':fields.explanation||'（空）'}</p><p role={f.field_constraints_valid?'status':'alert'}>{f.field_constraints_valid?'字段格式与引用范围已核对，含义未经人工核对。':'本条仍有字段或引用问题，不作为有效提取结果。'}</p>{f.issues.map((issue,i)=><p key={i}>{issue.message}</p>)}
 {resolved.length>0&&<SpanReferences refs={resolved.map(r=>r.span_ref)} catalog={catalog} preview={row.preview} account={account} writable={false} Btn={Btn}/>} {f.references.map((r,i)=>r.state!=='resolved'&&<p key={i}>原引用{i+1}：{refReasons[r.state]}；未据此显示有效证据。</p>)}{fields.span_refs===null?<p>原引用列表格式不正确，不能核对出处。</p>:fields.span_refs.length>16?<p>原回答列出{fields.span_refs.length}处引用，超过本批约定；未截取部分引用冒充完整依据。</p>:!fields.span_refs.length&&<p>原声明没有字面引用，不能当作已核事实。</p>}
 <details><summary>查看技术协议详情（原标识与引用）</summary><p>原内部标识：{f.protocol_key===null?'未以文字提供':f.protocol_key||'（空）'}</p>{fields.span_refs&&<ul>{fields.span_refs.map((ref,i)=><li key={i}>{ref}</li>)}</ul>}</details></details>;})}</>:<p>此保存回答当前不能作为事实清单展示。原回答仍保留；本页不展示原始JSON，也不另起调用。</p>}</>}
 <Btn onClick={()=>{sequence.current++;setLoading(false);setOpened(false);}}>收起已保存事实</Btn></>}
 </section>;
}

export function EvidenceNativeCapture({session,row,stage,Btn=Button,operate,checkEntry}){
 const target=stage==='reduce'?row.reduction:row.maps.find(s=>s.chunk_id===stage),view=session.captures[stage],receipt=target.receipt,error=session.captureErrors[stage];
 const labels={missing:target.reserved_call_id?'尚无已保存的模型回答，请先核对原调用；不会自动重新付费。':'本组尚未开始读取。',partial:'仅收到部分回答，现有内容已保存，暂时无法采用；原调用与费用保留，不会重发。',complete:'模型回答已完整保存，仍需核对内容。',quarantined:'已保存的回答需要排查，暂时无法采用；现有内容与费用记录保留。'};
 const text=view?labels[view.capture_state]:receipt?.response_complete===true&&evidenceIdentityEncoding(receipt.http_content_encoding)?'模型回答已完整保存，仍需核对内容。':target.reserved_call_id?'回答保存情况尚待核对；原调用与费用保留，不会自动重新付费。':'本组尚未开始读取。';
 async function download(){const expected=row.view_hash,blob=await session.downloadCapture(stage,view);checkEntry();if(session.row?.view_hash!==expected)throw Error('原稿版本已变化，未下载迟到内容。');const url=URL.createObjectURL(blob),link=document.createElement('a');try{link.href=url;link.download='report-evidence-'+stage+'-capture.bin';document.body.appendChild(link);checkEntry();link.click();}finally{link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}}
 return <section data-evidence-capture-stage={stage}><p role={view&&['partial','quarantined'].includes(view.capture_state)?'alert':'status'}>{text}</p>{error&&<p role="alert">暂时无法核对回答保存情况，已有记录保持不变；请展开排查后重试。</p>}<details><summary>排查回答保存情况（只读）</summary><p>以下读取与下载不解析、采用或修复原回答，也不发起模型调用。</p>{error&&<p role="alert">{error}</p>}<Btn onClick={()=>operate(()=>session.readCapture(stage))}>查看回答保存情况（只读）</Btn>{view&&<><p>已保存{view.body_bytes.toLocaleString()}字节；{view.http_status===null?'尚无HTTP状态':'原HTTP状态 '+view.http_status}。{view.content_encoding_safe?'编码记录可核对。':'编码尚未核对安全，不能当作普通正文。'}</p>{receipt&&<p>原回答位置：普通正文；原完成标记：{receipt.finish_reason||'未保存'}；实际工具调用数：{receipt.tool_call_count??'未保存'}。</p>}<Btn disabled={!view.capture_hash||!view.body_sha256} onClick={()=>operate(download)}>下载已保存原响应（仅排查，不采用）</Btn></>}</details></section>;
}

